/**
 * recoverDirtyReviewTestCase.js
 *
 * Local-execution recovery for Test Cases stuck in code review because the
 * underlying test-automation PR has become dirty (merge conflicts with main).
 *
 * The normal flow is:
 *   In Review - Passed/Failed -> pr_test_automation_review -> pr_approved -> merge
 *
 * When the PR is dirty, merge is impossible and review cannot complete. This
 * handler detects a dirty/conflicting PR and moves the ticket to "In Rework"
 * so the dedicated pr_test_automation_rework agent resolves the conflicts.
 */

var scmModule = require('./common/scm.js');
var configLoader = require('./configLoader.js');
var trackersModule = require('./common/trackers.js');

var PR_CACHE_FILE = 'outputs/.recover_dirty_prs_cache.json';
var PR_CACHE_TTL_MS = 5 * 60 * 1000;

function _now() {
    return new Date().getTime();
}

function _readCache() {
    try {
        var raw = file_read({ path: PR_CACHE_FILE });
        if (raw) {
            var parsed = JSON.parse(raw);
            if (parsed && parsed.timestamp && (_now() - parsed.timestamp) < PR_CACHE_TTL_MS) {
                return parsed.prList;
            }
        }
    } catch (e) {
        // ignore cache read errors
    }
    return null;
}

function _writeCache(prList) {
    try {
        var slim = prList.map(function(pr) {
            return {
                number: pr.number,
                title: pr.title,
                head: { ref: pr.head && pr.head.ref ? pr.head.ref : '' },
                mergeable: pr.mergeable,
                mergeable_state: pr.mergeable_state || pr.mergeableState,
                mergeableState: pr.mergeableState || pr.mergeable_state
            };
        });
        file_write({ path: PR_CACHE_FILE, content: JSON.stringify({ timestamp: _now(), prList: slim }) });
    } catch (e) {
        console.warn('Failed to write PR cache:', e.message || e);
    }
}

function _parseJson(raw) {
    if (typeof raw === 'string') {
        try { return JSON.parse(raw); } catch (e) { return raw; }
    }
    return raw;
}

function _toArray(raw) {
    var parsed = _parseJson(raw);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && parsed.value) return parsed.value;
    if (parsed && parsed.items) return parsed.items;
    return parsed ? [parsed] : [];
}

function listOpenPrsCached(scm, config) {
    var cached = _readCache();
    if (cached) {
        console.log('Using cached open PR list (' + cached.length + ' PRs)');
        return cached;
    }
    try {
        var prList = scm.listPrs('open');
        prList = _toArray(prList);
        _writeCache(prList);
        return prList;
    } catch (e) {
        console.error('Failed to list PRs:', e);
        return [];
    }
}

function findOpenPRForTicket(scm, config, ticketKey) {
    var prList = listOpenPrsCached(scm, config);
    return prList.find(function(pr) {
        // Exact ticket match only — avoid false positives like TS-135 matching TS-1359
        var titleMatch = pr.title && new RegExp('^' + ticketKey + '(\\b|\\s|[-:_])').test(pr.title);
        var ref = pr.head && pr.head.ref ? pr.head.ref : '';
        var branchMatch = ref === ticketKey || ref.endsWith('/' + ticketKey);
        return titleMatch || branchMatch;
    }) || null;
}

function action(params) {
    var ticketKey = params.ticket && params.ticket.key;
    var config = configLoader.loadProjectConfig(params.jobParams || params || {});
    var jiraConfig = config.jira;
    var tracker = trackersModule.createTracker(config, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

    if (!ticketKey) {
        console.error('No ticket key found');
        return { success: false, error: 'missing ticket key' };
    }

    console.log('Recovering dirty-review Test Case:', ticketKey);

    var scm = scmModule.createScm(config);
    var pr = findOpenPRForTicket(scm, config, ticketKey);

    if (!pr) {
        console.log('No open PR found for', ticketKey, '— nothing to recover');
        return { success: true, action: 'no_pr', ticketKey: ticketKey };
    }

    console.log('Found open PR #' + pr.number + ': ' + pr.title);

    var prDetail;
    // Avoid an extra API call if the PR list already returned mergeability info
    if (pr.mergeable !== undefined || pr.mergeableState || pr.mergeable_state) {
        prDetail = pr;
    } else {
        try {
            prDetail = scm.getPr(pr.number);
        } catch (e) {
            console.error('Failed to get PR details:', e);
            prDetail = pr;
        }
    }

    var mergeableState = prDetail && (prDetail.mergeable_state || prDetail.mergeableState || '');
    var mergeable = prDetail && prDetail.mergeable;
    console.log('PR #' + pr.number + ' mergeable=' + mergeable + ' state=' + mergeableState);

    var isDirty = mergeableState === 'dirty' || mergeableState === 'conflicting' || mergeable === false;
    if (!isDirty) {
        console.log('PR #' + pr.number + ' is clean — no recovery needed');
        return { success: true, action: 'clean', ticketKey: ticketKey, prNumber: pr.number };
    }

    console.log('PR #' + pr.number + ' is dirty — moving ticket to In Rework for conflict resolution');
    try {
        tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
        console.log('Moved', ticketKey, 'to In Rework');
    } catch (e) {
        console.error('Failed to move to In Rework:', e);
        return { success: false, error: e.toString(), ticketKey: ticketKey, prNumber: pr.number };
    }

    // Remove stale labels so the rework agent can pick it up
    try { tracker.removeLabel(ticketKey, 'sm_test_rework_triggered'); } catch (e) {}
    try { tracker.removeLabel(ticketKey, 'sm_test_automation_triggered'); } catch (e) {}
    try { tracker.removeLabel(ticketKey, 'sm_test_review_triggered'); } catch (e) {}

    try {
        tracker.postComment(ticketKey, '🔄 *Recovery*: Test Case PR #' + pr.number + ' became dirty while in code review. Moved to In Rework so the test-automation rework agent can resolve the merge conflicts.'
        );
    } catch (e) {
        console.warn('Failed to post recovery comment:', e);
    }

    return { success: true, action: 'moved_to_rework', ticketKey: ticketKey, prNumber: pr.number };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Check WIP Label Pre-Action
 * Checks if ticket has a work-in-progress label and stops processing if found
 * Returns false to stop processing, true to continue
 */

/**
 * Pre-action function to check for WIP label
 * 
 * @param {Object} params - Parameters from Teammate job
 * @param {Object} params.ticket - Jira ticket object
 * @param {Object} params.metadata - Job metadata containing contextId
 * @returns {boolean} false to stop processing, true to continue
 */

var configLoader = require('./configLoader.js');
var gh = require('./common/githubHelpers.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

function action(params) {
    try {
        const ticket = params.ticket;
        const metadata = params.metadata;

        console.log('=== Running checkWipLabel pre-action ===');
        console.log('Ticket key:', ticket && ticket.key ? ticket.key : '(missing)');
        console.log('Context ID:', metadata && metadata.contextId ? metadata.contextId : '(missing)');

        if (!ticket || !ticket.key) {
            throw new Error('Ticket not found or not provided: ensure inputJql targets a valid, existing Jira ticket');
        }
        if (!ticket || !metadata || !metadata.contextId) {
            console.log('No contextId in metadata, continuing with processing');
            return true;
        }

        // Dynamically generate WIP label from contextId
        const wipLabel = metadata.contextId + '_wip';
        const ticketKey = ticket.key;
        initTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        // Get ticket labels
        const labels = ticket.fields && ticket.fields.labels ? ticket.fields.labels : [];
        console.log('Expected WIP label:', wipLabel);
        console.log('Ticket labels:', labels.length > 0 ? labels.join(', ') : '(none)');

        // Check if WIP label exists
        if (labels.includes(wipLabel)) {
            console.log('⏸️  Ticket ' + ticketKey + ' has WIP label "' + wipLabel + '" - skipping processing');

            // Post comment to ticket explaining why it was skipped
            try {
                getTracker().postComment(ticketKey, 'h3. *Processing Skipped*\n\n' +
                            'This ticket has the *' + wipLabel + '* label indicating work is in progress.\n' +
                            'Processing will be skipped until the label is removed.\n\n' +
                            '_Remove the label to allow automated processing._');
                console.log('Posted skip notification comment to ' + ticketKey);
            } catch (commentError) {
                console.warn('Failed to post skip comment:', commentError);
            }

            console.log('checkWipLabel result: stop processing');
            return false; // Stop processing
        }

        console.log('✅ Ticket ' + ticketKey + ' does not have WIP label "' + wipLabel + '" - continuing with processing');

        // Optional: verify an open PR exists for review/rework agents.
        var customParams = (params.jobParams && params.jobParams.customParams) || params.customParams || {};
        if (customParams.checkOpenPR) {
            try {
                var config = configLoader.loadProjectConfig(params.jobParams || params);
                var scm = configLoader.createScm(config);
                var prSearchOptions = config.prSearchFn ? { prSearchFn: config.prSearchFn } : {};
                var pr = gh.findPRForTicket(scm, ticketKey, prSearchOptions);
                if (!pr) {
                    console.log('⏸️  No open PR found for ' + ticketKey + ' - skipping processing');
                    try {
                        getTracker().postComment(ticketKey, 'h3. *Processing Skipped*\n\nNo open Pull Request found for this ticket. The review/rework agent cannot run without an existing PR.\n\n_Ticket will be processed again once a PR is available._');
                    } catch (commentError) {
                        console.warn('Failed to post skip comment:', commentError);
                    }
                    console.log('checkWipLabel result: stop processing (no open PR)');
                    return false;
                }
                console.log('✅ Found open PR #' + pr.number + ' for ' + ticketKey + ' - continuing');
            } catch (prError) {
                console.warn('Failed to check open PR (non-fatal):', prError);
            }
        }

        console.log('checkWipLabel result: continue processing');
        return true; // Continue processing

    } catch (error) {
        // The ticket-not-found guard is a job-configuration error (inputJql
        // matched nothing), not a transient tool failure — rethrow it so the
        // job aborts instead of silently processing without a ticket. Every
        // other error keeps the continue-processing contract below.
        if (error && error.message && error.message.indexOf('Ticket not found') === 0) {
            throw error;
        }
        console.error('❌ Error in WIP label check:', error);
        // On error, continue processing to avoid blocking legitimate workflows
        console.warn('Continuing with processing despite error in WIP check');
        console.log('checkWipLabel result: continue processing after error');
        return true;
    }
}

