            './configLoader.js': {
                loadProjectConfig: function() {
                    return mocks.config || { jira: { statuses: { IN_REWORK: 'In Rework' } } };
                }
            },
            './common/trackers.js': { createTracker: function(config, customParams) {
                note('createTracker', [config, customParams]);
                return tracker;
            } }
