    try {
        tracker.postComment(ticketKey, '🔄 *Recovery*: Test Case PR #' + prNumber + ' became dirty while in code review. Moved to In Rework so the test-automation rework agent can resolve the merge conflicts.'
        );
    } catch (e) {
