        assert.deepEqual(result, { success: true, action: 'no_pr', ticketKey: 'TS-1' });
        assert.deepEqual(callNames(setup.calls), ['listPrs', 'file_write']);
        assert.equal(setup.calls[0].args[0], 'open');
